        }
    }
    ["commit-msg"] {
        steps {
            ["entire"] {
                check = #"command -v entire >/dev/null 2>&1 && entire hooks git commit-msg {{commit_msg_file}} || true"#
            }
            ["commitlint"] {
                check = "npx commitlint --edit {{commit_msg_file}}"
            }
        }
