            }
        }
    }
    ["post-rewrite"] {
        steps {
            ["entire"] {
                check = #"command -v entire >/dev/null 2>&1 && entire hooks git post-rewrite {{hook_args}} || true"#
            }
        }
    }
    ["pre-push"] {
        steps {
            ["repository-control-plane"] {
                check = "npx nx run repository:pre-push"
            }
            ["entire"] {
                check = #"command -v entire >/dev/null 2>&1 && sh -c 'entire hooks git pre-push "$1"' -- {{hook_args}} || true"#
            }
        }
    }
    ["fix"] {
        fix = true
        steps = linters
    }
    ["check"] {
        steps = linters
    }
}
